package com.johnny.hotel.ar;
import com.johnny.hotel.ar.ArModels.*;import com.johnny.hotel.businessdate.BusinessDateService;import com.johnny.hotel.entity.*;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.mapper.*;import com.johnny.hotel.pagination.*;import com.johnny.hotel.payment.*;import com.johnny.hotel.service.FolioFinancialService;import lombok.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class ArService {private static final Set<String>TYPES=Set.of("COMPANY","TRAVEL_AGENCY","OTA","GOVERNMENT","CONTRACT_ACCOUNT","OTHER");private static final Set<String>METHODS=Set.of("BANK_TRANSFER","CARD","CASH","OTHER");private final ArMapper db;private final ArAccess access;private final FolioMapper folios;private final FolioFinancialService financial;private final BusinessDateService dates;private final PaymentCoreMapper transactions;private final SysAuditLogMapper audits;private final PaginationSupport pages;private final Clock clock;
 private void require(boolean b,String m){if(!b)throw new BusinessException(m);}private void one(int n){if(n!=1)throw new BusinessException(409,"AR state changed");}private String text(String s,int n,boolean required){String v=s==null?null:s.trim();if(required)require(v!=null&&!v.isEmpty(),"Required AR field missing");if(v!=null)require(v.length()<=n,"AR field too long");return v;}private BigDecimal money(BigDecimal v){require(v!=null&&v.signum()>0&&v.scale()<=2&&v.precision()-v.scale()<=10,"Invalid AR amount");return v.setScale(2);}
 @Transactional public AccountView create(AccountRequest r){var a=access.actor();String type=text(r.accountType,30,true).toUpperCase();require(TYPES.contains(type),"Unsupported AR account type");var x=ArAccount.builder().accountType(type).name(text(r.name,150,true)).currency(r.currency.toUpperCase()).creditLimit(r.creditLimit==null?null:r.creditLimit.setScale(2)).paymentTermsDays(r.paymentTermsDays).contactName(text(r.contactName,120,false)).contactEmail(text(r.contactEmail,120,false)).externalReference(text(r.externalReference,100,false)).createdBy(a.id()).build();one(db.insertAccount(x));audit(a.id(),"CREATE_AR_ACCOUNT",x.getId());return view(db.account(x.getId()));}
 @Transactional public AccountView status(Long id,String status){var a=access.actor();var x=db.lockAccount(id);require(x!=null,"AR account not found");String s=text(status,12,true).toUpperCase();require(Set.of("ACTIVE","INACTIVE").contains(s),"Invalid AR account status");if(!s.equals(x.getStatus()))one(db.status(id,s));audit(a.id(),"AR_ACCOUNT_"+s,id);return view(db.account(id));}
 @Transactional public ArLedgerEntry transfer(Long accountId,Long folioId,TransferRequest r){var actor=access.actor();String key=text(r.requestKey,100,true);request(key);var old=db.byRequest(key);if(old!=null){same(old,accountId,folioId,"FOLIO_TRANSFER",r.amount);return old;}var f=folios.selectByIdForUpdate(folioId);require(f!=null&&f.getClosedTime()==null,"Folio is unavailable for Direct Bill");var a=db.lockAccount(accountId);require(a!=null&&"ACTIVE".equals(a.getStatus()),"AR account is inactive or missing");require(a.getCurrency().equals(f.getCurrency()),"AR account currency mismatch");var summary=financial.recalculateSummary(folioId);BigDecimal amount=money(r.amount);require(summary.getBalanceAmount().signum()>0&&amount.compareTo(summary.getBalanceAmount())<=0,"Transfer exceeds Folio outstanding");BigDecimal outstanding=db.outstanding(accountId);if(a.getCreditLimit()!=null)require(outstanding.add(amount).compareTo(a.getCreditLimit())<=0,"AR credit limit exceeded");var e=entry(accountId,"FOLIO_TRANSFER",amount,a.getCurrency(),folioId,"FOLIO_TRANSFER",folioId,key,text(r.reason,500,false),null,null,actor.id(),dates.postingDate());one(db.insert(e));financial.recalculateSummary(folioId);audit(actor.id(),"FOLIO_DIRECT_BILL",e.getId());return e;}
 @Transactional public ArLedgerEntry pay(Long accountId,PaymentRequest r){var actor=access.actor();String key=text(r.requestKey,100,true);request(key);var old=db.byRequest(key);if(old!=null){same(old,accountId,null,"PAYMENT",r.amount);return old;}var a=db.lockAccount(accountId);require(a!=null,"AR account not found");BigDecimal amount=money(r.amount),out=db.outstanding(accountId);require(amount.compareTo(out)<=0,"AR payment exceeds outstanding");String method=text(r.paymentMethod,30,true).toUpperCase();require(METHODS.contains(method),"Unsupported AR payment method");LocalDate bd=dates.postingDate();LocalDateTime now=LocalDateTime.now(clock);var e=entry(accountId,"PAYMENT",amount,a.getCurrency(),null,"AR_PAYMENT",null,key,null,method,text(r.externalReference,100,false),actor.id(),bd);e.setOccurredAt(now);one(db.insert(e));one(transactions.insertTransaction(HotelTransactionRecord.builder().direction("EXTERNAL_IN").amount(amount).currency(a.getCurrency()).sourceType("AR_PAYMENT").sourceId(e.getId()).businessReferenceType("AR_ACCOUNT").businessReferenceId(accountId).paymentMethod(method).channel("AR").provider("OFFLINE").providerTransactionId(e.getExternalReference()).initiatorType("FINANCE").operatorUserId(actor.id()).description("AR account payment").occurredAt(now).businessDate(bd).build()));audit(actor.id(),"AR_PAYMENT",e.getId());return e;}
 @Transactional public ArLedgerEntry credit(Long accountId,CreditRequest r){var actor=access.actor();String key=text(r.requestKey,100,true);request(key);var old=db.byRequest(key);if(old!=null){same(old,accountId,null,"CREDIT",r.amount);return old;}var a=db.lockAccount(accountId);require(a!=null,"AR account not found");BigDecimal amount=money(r.amount),out=db.outstanding(accountId);require(amount.compareTo(out)<=0,"AR credit exceeds outstanding");var e=entry(accountId,"CREDIT",amount,a.getCurrency(),null,"AR_CREDIT",null,key,text(r.reason,500,true),null,null,actor.id(),dates.postingDate());one(db.insert(e));audit(actor.id(),"AR_CREDIT",e.getId());return e;}
 @Transactional(readOnly=true)public PageResult<java.util.Map<String,Object>> accounts(Integer page,Integer size){access.actor();var w=pages.window(page,size,true);return pages.result(w,db.accountBalances(w.offset(),pages.limit(w)),db.accountCount());}
 @Transactional(readOnly=true)public AccountView get(Long id){access.actor();var a=db.account(id);require(a!=null,"AR account not found");return view(a);}@Transactional(readOnly=true)public PageResult<ArLedgerEntry> statement(Long id,Integer page,Integer size){access.actor();require(db.account(id)!=null,"AR account not found");var w=pages.window(page,size,true);return pages.result(w,db.entries(id,w.offset(),pages.limit(w)),db.count(id));}
 private AccountView view(ArAccount a){BigDecimal o=db.outstanding(a.getId());return AccountView.builder().account(a).outstanding(o).availableCredit(a.getCreditLimit()==null?null:a.getCreditLimit().subtract(o)).build();}private ArLedgerEntry entry(Long aid,String type,BigDecimal amount,String cur,Long fid,String source,Long sid,String key,String reason,String method,String ref,Long actor,LocalDate bd){return ArLedgerEntry.builder().accountId(aid).entryType(type).amount(amount).currency(cur).folioId(fid).sourceType(source).sourceId(sid).requestKey(key).reason(reason).paymentMethod(method).externalReference(ref).operatorUserId(actor).postingBusinessDate(bd).occurredAt(LocalDateTime.now(clock)).build();}
 private void request(String key){db.ensureRequest(key);require(key.equals(db.lockRequest(key)),"AR request lock failed");}private void same(ArLedgerEntry e,Long aid,Long fid,String type,BigDecimal amount){require(e.getAccountId().equals(aid)&&Objects.equals(e.getFolioId(),fid)&&type.equals(e.getEntryType())&&e.getAmount().compareTo(money(amount))==0,"AR request key conflict");}private void audit(Long actor,String action,Long id){one(audits.insert(SysAuditLog.builder().operatorId(actor).action(action).detail("AR "+id).build()));}
}
